-- Additive discovery audit schema. All reads and writes must bind tenant_id.
CREATE TABLE IF NOT EXISTS discovery_scanners (id VARCHAR(64) PRIMARY KEY, tenant_id VARCHAR(64) NOT NULL, hostname VARCHAR(255) NOT NULL, version VARCHAR(64), status VARCHAR(32) NOT NULL DEFAULT 'OFFLINE', capabilities JSON, last_seen_at DATETIME NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, KEY idx_scanner_tenant (tenant_id));
CREATE TABLE IF NOT EXISTS discovery_scans (id VARCHAR(64) PRIMARY KEY, tenant_id VARCHAR(64) NOT NULL, scanner_id VARCHAR(64) NULL, method VARCHAR(64) NOT NULL, target_range VARCHAR(255) NOT NULL, status VARCHAR(32) NOT NULL, started_at DATETIME NULL, completed_at DATETIME NULL, devices_found INT NOT NULL DEFAULT 0, devices_updated INT NOT NULL DEFAULT 0, devices_created INT NOT NULL DEFAULT 0, devices_failed INT NOT NULL DEFAULT 0, error_count INT NOT NULL DEFAULT 0, KEY idx_scan_tenant (tenant_id));
CREATE TABLE IF NOT EXISTS raw_discovery_results (id VARCHAR(64) PRIMARY KEY, tenant_id VARCHAR(64) NOT NULL, scan_id VARCHAR(64) NOT NULL, source_id VARCHAR(64) NULL, target VARCHAR(255) NULL, protocol VARCHAR(32) NULL, raw_payload JSON NOT NULL, received_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, processing_status VARCHAR(32) NOT NULL, error_message TEXT NULL, KEY idx_raw_tenant_scan (tenant_id, scan_id));
CREATE TABLE IF NOT EXISTS discovery_attributes (id VARCHAR(64) PRIMARY KEY, tenant_id VARCHAR(64) NOT NULL, ci_id VARCHAR(64) NOT NULL, attribute_name VARCHAR(128) NOT NULL, attribute_value JSON NULL, source VARCHAR(64) NOT NULL, source_type VARCHAR(64) NOT NULL, confidence VARCHAR(16) NULL, discovered_at DATETIME NOT NULL, last_seen_at DATETIME NOT NULL, KEY idx_attribute_tenant_ci (tenant_id, ci_id));
